<?php
namespace App\Livewire\Admin\Access;use App\Models\Permission;use App\Models\PermissionGroup;use Illuminate\Support\Facades\DB;use Illuminate\Validation\Rule;use Livewire\Component;
class Groups extends Component{public ?int $editing_id=null;public string $name='';public string $display_name='';public string $description='';public array $permission_ids=[];public function mount():void{abort_unless(auth()->user()->isAdmin(),403);}public function edit(int $id):void{$g=PermissionGroup::with('permissions')->findOrFail($id);$this->editing_id=$g->id;$this->name=$g->name;$this->display_name=$g->display_name;$this->description=$g->description??'';$this->permission_ids=$g->permissions->pluck('id')->all();}public function resetForm():void{$this->reset(['editing_id','name','display_name','description','permission_ids']);}public function save():void{$d=$this->validate(['name'=>['required','string','max:255',Rule::unique('permission_groups')->ignore($this->editing_id)],'display_name'=>['required','string','max:255'],'description'=>['nullable','string','max:2000'],'permission_ids'=>['array'],'permission_ids.*'=>['integer','exists:permissions,id']]);DB::transaction(function()use($d){$g=PermissionGroup::updateOrCreate(['id'=>$this->editing_id],collect($d)->except('permission_ids')->all());$g->permissions()->sync($d['permission_ids']);});$this->resetForm();session()->flash('success','Permission group saved.');}public function delete(int $id):void{$g=PermissionGroup::withCount('users')->findOrFail($id);abort_if($g->users_count>0,422,'Remove this group from users before deleting it.');$g->delete();}public function render(){return view('livewire.admin.access.groups',['groups'=>PermissionGroup::withCount(['permissions','users'])->orderBy('display_name')->get(),'permissions'=>Permission::orderBy('resource')->orderBy('action')->get()->groupBy('resource')])->layout('components.layouts.admin',['title'=>'Permission groups']);}}
